absl::StatusOr<std::unique_ptr<SExpression>>
SirToAst::VisitExpression(SirExpressionOpInterface op) {
  using Ret = absl::StatusOr<std::unique_ptr<SExpression>>;
  return llvm::TypeSwitch<mlir::Operation*, Ret>(op)
    .Case([&](SirIdentifierOp op) {
      return VisitIdentifier(op);
    })
    .Case([&](SirCallOp op) {
      return VisitCall(op);
    })
    .Case([&](SirMemberOp op) {
      return VisitMember(op);
    })
    .Default([&](mlir::Operation* op) {
      return absl::InvalidArgumentError("Unrecognized op");
    });
}

absl::StatusOr<std::unique_ptr<SPattern>>
SirToAst::VisitPatternRef(SirPatternRefOpInterface op) {
  using Ret = absl::StatusOr<std::unique_ptr<SPattern>>;
  return llvm::TypeSwitch<mlir::Operation*, Ret>(op)
    .Case([&](SirIdentifierRefOp op) {
      return VisitIdentifierRef(op);
    })
    .Default([&](mlir::Operation* op) {
      return absl::InvalidArgumentError("Unrecognized op");
    });
}

absl::StatusOr<std::unique_ptr<SStatement>>
SirToAst::VisitStatement(SirStatementOpInterface op) {
  using Ret = absl::StatusOr<std::unique_ptr<SStatement>>;
  return llvm::TypeSwitch<mlir::Operation*, Ret>(op)
    .Case([&](SirDeclarationOp op) {
      return VisitDeclaration(op);
    })
    .Case([&](SirExpressionStatementOp op) {
      return VisitExpressionStatement(op);
    })
    .Case([&](SirLoopOp op) {
      return VisitLoop(op);
    })
    .Default([&](mlir::Operation* op) {
      return absl::InvalidArgumentError("Unrecognized op");
    });
}

